package com.neueda.leap.trading.identity;
import java.util.UUID; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional;
@Component public class SuperAdminBootstrap implements ApplicationRunner {
 private final IdentityMapper mapper;private final PasswordEncoder passwords;private final String email,password;
 public SuperAdminBootstrap(IdentityMapper mapper,PasswordEncoder passwords,@Value("${app.bootstrap.super-admin.email:superadmin@trading.demo}")String email,@Value("${app.bootstrap.super-admin.password:}")String password){this.mapper=mapper;this.passwords=passwords;this.email=email.toLowerCase();this.password=password;}
 @Override @Transactional public void run(ApplicationArguments args){if(mapper.emailCount(email)>0)return;if(password==null||password.isBlank())throw new IllegalStateException("SUPER_ADMIN_PASSWORD (app.bootstrap.super-admin.password) must be set for first startup");UUID id=UUID.randomUUID();mapper.insertSuperAdmin(id,email,passwords.encode(password));if(mapper.insertRole(id,"SUPER_ADMIN")!=1)throw new IllegalStateException("SUPER_ADMIN role not found");}
}